.ludo-scene .ludo-board{position:relative;display:grid;grid-template-columns:repeat(15,minmax(0,1fr));grid-template-rows:repeat(15,minmax(0,1fr));width:100%;height:100%;aspect-ratio:1;box-sizing:border-box;border:var(--size-border-2_0,2px) solid var(--color-material-route-rim,#8e9c7d);background:var(--color-material-route-face,#fff8e8);border-radius:var(--size-radius-8_0,8px);overflow:hidden;}.ludo-scene .ludo-cell{display:grid;place-items:center;min-width:0;min-height:0;border:var(--size-border-1_0,1px) solid var(--color-material-route-grid,#bbc8ad);box-sizing:border-box;aspect-ratio:1;font:700 clamp(var(--size-type-6_0,10px),1.8vmin,var(--size-type-16_0,16px))/1 system-ui;color:#fffbed;}.ludo-scene .ludo-base{padding:18%;background:var(--base);box-sizing:border-box;}.ludo-scene .ludo-base>div{display:grid;grid-template-columns:1fr 1fr;gap:15%;width:100%;height:100%;padding:12%;box-sizing:border-box;border-radius:16%;background:var(--color-material-route-base,#fff9e7);}.ludo-scene .ludo-base span{border-radius:50%;background:var(--base);opacity:.32;aspect-ratio:1;}.ludo-scene .ludo-center{position:relative;grid-column:7/span 3;grid-row:7/span 3;}.ludo-scene .ludo-center svg{display:block;width:100%;height:100%;}.ludo-scene .ludo-center>span{position:absolute;inset:30%;width:40%;height:40%;}.ludo-scene .ludo-pawn{position:absolute;display:grid;place-items:center;width:var(--pawn-size,5.4%);height:auto;aspect-ratio:1;min-width:0;min-height:0;padding:0;border:0;border-radius:50%;outline:none!important;background:transparent;transform:translate(-50%,-50%);z-index:2;--round-token-fill:var(--pawn);--round-token-side:color-mix(in srgb,var(--pawn) 65%,black);--round-token-mark:#fffdf4;--round-token-rim:#fff8e9;}.ludo-scene .ludo-pawn:disabled{opacity:1;pointer-events:none;}.ludo-scene .ludo-pawn.is-playable{outline:0;box-shadow:0 0 0 2px #254833;z-index:4;}.ludo-scene .ludo-pawn.is-playable::after{content:"";position:absolute;inset:-7px;border-radius:50%;}
.ludo-scene .ludo-pawn.is-selected{outline:0;box-shadow:0 0 0 3px #e5b735;z-index:5;}
.ludo-scene .ludo-pawn-art{display:block;width:100%;height:100%;aspect-ratio:1;overflow:visible;}
.ludo-scene .ludo-pawn.is-tiny .ludo-pawn-digit{display:none;}
.ludo-scene .ludo-pawn.is-playable::after{inset:-2px;}
.ludo-scene .ludo-cell{position:relative;padding:0;border-radius:0;box-shadow:none;}
.ludo-scene .ludo-safe{color:var(--color-material-route-star,#376746);background:var(--color-material-route-safe,#d8e6ca);}
.ludo-scene .ludo-safe-star{display:block;width:100%;height:100%;color:var(--color-material-route-star,#376746);pointer-events:none;}
.ludo-scene .ludo-start-arrow{display:block;width:80%;height:80%;color:#fffbea;filter:drop-shadow(0 1px 1px #29422f88);pointer-events:none;}
.ludo-scene .ludo-cell[data-motion-anchor^="finish-"]:not(.ludo-target){visibility:hidden;}
.ludo-scene .ludo-pawn:focus-visible{outline:0;box-shadow:0 0 0 3px #172f25;}
.ludo-scene .shared-die.used{opacity:.4;filter:grayscale(1);}
.ludo-scene .shared-die.is-playable{outline:var(--size-border-3_0,2px) solid #c4a344;outline-offset:2px;}
.ludo-scene .shared-action-row{flex-wrap:wrap;}.ludo-scene .shared-hint{flex-basis:100%;text-align:center;}

/* A home/capture fill must not hide the same gold target edge used on plain cells. */
.ludo-scene .ludo-target{--target-edge:#96720b}

